drills.solution:
export async function reserveSeat(store, seatId, userId) {
  const seat = await store.get(seatId);
  if (!seat) return { ok: false, reason: 'not-found' };
  if (seat.heldBy !== null) return { ok: false, reason: 'taken' };
  const next = { ...seat, heldBy: userId, version: seat.version + 1 };
  const won = await store.putIfVersion(seatId, next, seat.version);
  return won ? { ok: true } : { ok: false, reason: 'taken' };
}

