drills.solution:
export async function withRetryOnConflict(store, id, mutate, maxAttempts) {
  for (let attempts = 1; attempts <= maxAttempts; attempts++) {
    const current = await store.get(id);
    if (!current) return { status: 404 };
    const row = { ...mutate(current), id: current.id, version: current.version + 1 };
    if (await store.putIfVersion(id, row, current.version)) return { status: 200, row, attempts };
  }
  return { status: 409, attempts: maxAttempts };
}

